#include <bits/stdc++.h>
using namespace std;
const long long MOD=1e9+7;
int main(){ string s; cin>>s;
  long long s0=0,s1=1,s2=1; // virtual border
  for(char c: s){ long long n0=0,n1=0,n2=0;
    if(c=='#'||c=='?') n0=(s0+s1)%MOD;
    for(int d=0; d<=2; d++){ if(!(c=='?'||c=='0'+d)) continue;
      for(int from=0; from<2; from++){ // from=0 -> prev mine(s0), 1 -> s2
        long long w= from==0? s0:s2; int left= from==0;
        int need=d-left; if(need==1) n1=(n1+w)%MOD; else if(need==0) n2=(n2+w)%MOD; } }
    s0=n0; s1=n1; s2=n2; }
  cout<<(s0+s2)%MOD<<endl; }

#include <bits/stdc++.h>
using namespace std;
typedef long long ll; vector<ll> a; ll X,Y;
ll f(int l,int r,ll base){ // a[l..r] all > base
  if(l>r) return 0;
  ll m=*min_element(a.begin()+l,a.begin()+r+1);
  ll A=Y*(r-l+1), B=X*(m-base);
  int s=l;
  for(int i=l;i<=r+1;i++) if(i==r+1||a[i]==m){ B+=f(s,i-1,m); s=i+1; if(B>=A) break; }
  return min(A,B);
}
int main(){ int n; cin>>n>>X>>Y; a.resize(n); for(auto&x:a)cin>>x;
  ll ans=0; int s=0;
  for(int i=0;i<=n;i++) if(i==n||a[i]==0){ ans+=f(s,i-1,0); s=i+1; }
  cout<<ans<<endl; }

#include <bits/stdc++.h>
using namespace std;
const long long MOD=1e9+7; const int MX=100001;
int spf[MX]; int e[MX]; double cur=0;
void upd(int x,int s){ while(x>1){int p=spf[x]; x/=p; cur-=log(e[p]+1.0); e[p]+=s; cur+=log(e[p]+1.0);} }
int main(){ for(int i=2;i<MX;i++) if(!spf[i]) for(int j=i;j<MX;j+=i) if(!spf[j]) spf[j]=i;
  int n,X; cin>>n>>X; vector<int> a(n+1); for(int i=1;i<=n;i++) cin>>a[i];
  double lim=log((double)X)-1e-9;
  vector<long long> dp(n+1,0), P(n+1,0); dp[0]=P[0]=1; int l=1;
  for(int r=1;r<=n;r++){ upd(a[r],1);
    while(l<r){ upd(a[l],-1); if(cur>=lim){ l++; } else { upd(a[l],1); break; } }
    dp[r]= cur>=lim ? P[l-1] : 0;
    P[r]=(P[r-1]+dp[r])%MOD; }
  cout<<dp[n]%MOD<<endl; }

#include <bits/stdc++.h>
using namespace std; typedef long long ll; const ll INF=LLONG_MAX/4;
int sz; vector<ll> t;
void upd(int p,ll v){ for(t[p+=sz]=v; p>1; p>>=1) t[p>>1]=min(t[p],t[p^1]); }
ll qry(int l,int r){ ll res=INF; for(l+=sz,r+=sz+1; l<r; l>>=1,r>>=1){ if(l&1) res=min(res,t[l++]); if(r&1) res=min(res,t[--r]); } return res; }
int main(){ int n,M; cin>>n>>M; vector<ll> a(n+1); for(int i=1;i<=n;i++) cin>>a[i];
  sz=n+1; t.assign(2*sz,INF); vector<ll> dp(n+1,INF); dp[0]=0; upd(0,0);
  vector<pair<ll,int>> cur; // (or value, smallest start), starts descending
  for(int i=1;i<=n;i++){ vector<pair<ll,int>> nx; nx.push_back({a[i],i});
    for(auto [v,l]: cur){ ll w=v|a[i]; if(w==nx.back().first) nx.back().second=l; else nx.push_back({w,l}); }
    cur=nx; int hi=i; int lo_lim=max(1,i-M+1);
    for(auto [v,l]: cur){ int lo=max(l,lo_lim); if(lo<=hi) dp[i]=min(dp[i], qry(lo-1,hi-1)+v); hi=l-1; if(hi<lo_lim) break; }
    upd(i,dp[i]); }
  cout<<dp[n]%1000000007LL<<endl; }

#include <bits/stdc++.h>
using namespace std;
int getLengthOfOptimalCompression(string s,int K){ int n=s.size();
  auto cost=[](int c){ return 1+(c>1)+(c>=10)+(c>=100); };
  vector<vector<int>> dp(n+1, vector<int>(K+1, 0));
  for(int i=n-1;i>=0;i--) for(int k=0;k<=K;k++){
    int best= k? dp[i+1][k-1] : INT_MAX;
    int same=0, del=0;
    for(int j=i;j<n;j++){ if(s[j]==s[i]) same++; else del++;
      if(del>k) break; best=min(best, cost(same)+dp[j+1][k-del]); }
    dp[i][k]=best; }
  return dp[0][K]; }
int main(){ string s; int k; cin>>s>>k; cout<<getLengthOfOptimalCompression(s,k)<<endl; }

