int main(){ int n; cin>>n; vector<long long> a(n+1); for(int i=1;i<=n;i++) cin>>a[i];
  vector<vector<short>> lis(n+2, vector<short>(n+1,0));
  for(int l=1;l<=n;l++){ vector<long long> t;
    for(int r=l;r<=n;r++){ auto it=lower_bound(t.begin(),t.end(),a[r]);
      if(it==t.end()) t.push_back(a[r]); else *it=a[r]; lis[l][r]=t.size(); } }
  vector<vector<int>> P(n+1, vector<int>(n+1,0));
  for(int x=0;x<=n;x++) P[0][x]=1;
  for(int i=1;i<=n;i++){ vector<long long> dp(n+1,0);
    for(int j=0;j<i;j++){ int b=lis[j+1][i]; dp[b]=(dp[b]+P[j][b-1])%MOD; }
    long long s=0; for(int x=0;x<=n;x++){ s=(s+dp[x])%MOD; P[i][x]=s; } }
  cout<<P[n][n]<<endl; }

#include <bits/stdc++.h>
using namespace std; const long long NEG=LLONG_MIN/4;
int main(){ int n,K; cin>>n>>K; int m=3*n; vector<long long> a(m); for(auto&x:a)cin>>x;
  long long ans=NEG;
  for(int f=0; f<2; f++){
    vector<vector<array<long long,2>>> dp(n+2, vector<array<long long,2>>(K+2,{NEG,NEG}));
    if(f) dp[1][0][1]=a[0]; else dp[0][0][0]=0;
    for(int i=1;i<m;i++){ auto nd=vector<vector<array<long long,2>>>(n+2, vector<array<long long,2>>(K+2,{NEG,NEG}));
      for(int c=0;c<=n;c++) for(int t=0;t<=K;t++) for(int l=0;l<2;l++){ long long v=dp[c][t][l]; if(v==NEG) continue;
        nd[c][t][0]=max(nd[c][t][0],v);
        if(c<n && t+l<=K) nd[c+1][t+l][1]=max(nd[c+1][t+l][1], v+a[i]); }
      dp=nd; }
    for(int t=0;t<=K;t++) for(int l=0;l<2;l++){ long long v=dp[n][t][l]; if(v==NEG) continue;
      if(t+(f&&l)<=K) ans=max(ans,v); } }
  cout<<ans<<endl; }

#include <bits/stdc++.h>
using namespace std;
struct BIT{ int n; vector<int> t; BIT(int n):n(n),t(n+1,0){} void upd(int i,int v){for(;i<=n;i+=i&-i) t[i]=max(t[i],v);} int q(int i){int r=0; for(;i>0;i-=i&-i) r=max(r,t[i]); return r;} };
int main(){ int n; long long M; cin>>n>>M; vector<long long> p(n); for(auto&x:p)cin>>x;
  vector<long long> v=p; sort(v.begin(),v.end()); v.erase(unique(v.begin(),v.end()),v.end()); int k=v.size();
  // pre[d][u]: prefix max by value; suf[d][u]: prefix max on reversed index
  vector<BIT> pre(4,BIT(k)), suf(4,BIT(k)); int ans=0;
  for(int i=0;i<n;i++){
    int lo=upper_bound(v.begin(),v.end(),p[i]-M)-v.begin();           // count of values <= p-M
    int hi=v.end()-lower_bound(v.begin(),v.end(),p[i]+M);             // count of values >= p+M
    auto P=[&](int d,int u){return pre[d*2+u].q(lo);};
    auto S=[&](int d,int u){return suf[d*2+u].q(hi);};
    int U0=1+P(1,0), U1=1+max(P(1,1),P(0,0)), D0=1+S(0,0), D1=1+max(S(0,1),S(1,0));
    // a lone element (value 1) is already covered since queries return >=0
    int vals[4]={U0,U1,D0,D1}; // index d*2+u with d=0 up, d=1 down
    int pos=lower_bound(v.begin(),v.end(),p[i])-v.begin();
    for(int s=0;s<4;s++){ pre[s].upd(pos+1,vals[s]); suf[s].upd(k-pos,vals[s]); ans=max(ans,vals[s]); } }
  cout<<ans<<endl; }

