#include <bits/stdc++.h>
using namespace std; typedef long long ll; const ll INF=1e18;
int N; vector<ll> t,lz;
void build(int x,int l,int r,vector<ll>&v){ lz[x]=0; if(l==r){t[x]=v[l];return;} int m=(l+r)/2; build(2*x,l,m,v); build(2*x+1,m+1,r,v); t[x]=min(t[2*x],t[2*x+1]); }
void add(int x,int l,int r,int ql,int qr,ll v){ if(qr<l||r<ql) return; if(ql<=l&&r<=qr){t[x]+=v; lz[x]+=v; return;}
  int m=(l+r)/2; add(2*x,l,m,ql,qr,v); add(2*x+1,m+1,r,ql,qr,v); t[x]=min(t[2*x],t[2*x+1])+lz[x]; }
ll qry(int x,int l,int r,int ql,int qr){ if(qr<l||r<ql) return INF; if(ql<=l&&r<=qr) return t[x];
  int m=(l+r)/2; return min(qry(2*x,l,m,ql,qr),qry(2*x+1,m+1,r,ql,qr))+lz[x]; }
int main(){ int n,k; cin>>n>>k; vector<int> a(n+1), prv(n+1,0); map<int,int> last;
  for(int i=1;i<=n;i++){ cin>>a[i]; if(last.count(a[i])) prv[i]=last[a[i]]; last[a[i]]=i; }
  N=n+1; t.assign(4*N,0); lz.assign(4*N,0);
  vector<ll> dp(n+1,INF); dp[0]=0;
  for(int layer=1; layer<=k; layer++){ build(1,0,n,dp); vector<ll> nd(n+1,INF);
    for(int i=1;i<=n;i++){ if(prv[i]>0) add(1,0,n,0,prv[i]-1,i-prv[i]); nd[i]=min(INF,qry(1,0,n,0,i-1)); }
    dp=nd; }
  cout<<dp[n]<<endl; }

