#include <bits/stdc++.h>
using namespace std; typedef long long ll; const ll MOD=1e9+7;
ll pw(ll b,ll e){ll r=1;b%=MOD;while(e){if(e&1)r=r*b%MOD;b=b*b%MOD;e>>=1;}return r;}
int main(){ int n,m; cin>>n>>m; vector<int> X(m),Y(m); for(auto&x:X)cin>>x; for(auto&y:Y)cin>>y;
  vector<ll> f(n+1,1), inv(n+1,1); for(int i=1;i<=n;i++) f[i]=f[i-1]*i%MOD;
  inv[n]=pw(f[n],MOD-2); for(int i=n;i>0;i--) inv[i-1]=inv[i]*i%MOD;
  auto C=[&](int a,int b){ return f[a]*inv[b]%MOD*inv[a-b]%MOD; };
  ll mult=f[n]; for(int x: X) mult=mult*inv[x]%MOD;
  vector<ll> dp(n+1,0); dp[0]=1; int tot=0;
  for(int i=0;i<m;i++){ vector<ll> nd(n+1,0); tot+=X[i];
    for(int p0=0;p0+X[i]<=tot && p0<=n;p0++){ if(!dp[p0]) continue; int p=p0+X[i];
      for(int s=0;s<=min(Y[i],p);s++) nd[p-s]=(nd[p-s]+dp[p0]*C(p,s))%MOD; }
    dp=nd; }
  cout<<mult*dp[0]%MOD<<endl; }

#include <bits/stdc++.h>
using namespace std; typedef long long ll; const ll MOD=1e9+7; const int K=100;
typedef vector<vector<ll>> Mat;
Mat mul(const Mat&A,const Mat&B){ Mat C(K,vector<ll>(K,0)); for(int i=0;i<K;i++) for(int k=0;k<K;k++){ if(!A[i][k]) continue; ll a=A[i][k];
  for(int j=0;j<K;j++) C[i][j]=(C[i][j]+a*B[k][j])%MOD; } return C; }
int main(){ int n; ll W; cin>>n>>W; vector<ll> cnt(K+1,0); for(int i=0;i<n;i++){int x;cin>>x;cnt[x]++;}
  vector<ll> dp(K,0); dp[0]=1;
  for(int w=1;w<K;w++) for(int v=1;v<=w;v++) dp[w]=(dp[w]+cnt[v]*dp[w-v])%MOD;
  if(W<K){ cout<<dp[W]<<endl; return 0; }
  Mat T(K,vector<ll>(K,0)), R(K,vector<ll>(K,0));
  for(int j=0;j<K;j++) T[0][j]=cnt[j+1]; for(int i=1;i<K;i++) T[i][i-1]=1; for(int i=0;i<K;i++) R[i][i]=1;
  for(ll e=W-(K-1); e; e>>=1, T=mul(T,T)) if(e&1) R=mul(R,T);
  ll ans=0; for(int j=0;j<K;j++) ans=(ans+R[0][j]*dp[K-1-j])%MOD;  // state[j]=dp[99-j]
  cout<<ans<<endl; }

