    for(int j=i;j>=1;j--){ if(a[j]>=0 && a[j]<=W) seen[a[j]]=1; while(seen[mex]) mex++;
      dp[mex]=(dp[mex]+P[j-1][mex])%MOD; }
    ll s=0; for(int m=0;m<W;m++){ s=(s+dp[m])%MOD; P[i][m]=s; } }
  cout<<P[n][W-1]<<endl; }

