using namespace std; const int NEG=-1e9;
vector<int> t,lz;
void build(int x,int l,int r,vector<int>&v){ lz[x]=0; if(l==r){t[x]=v[l];return;} int m=(l+r)/2; build(2*x,l,m,v); build(2*x+1,m+1,r,v); t[x]=max(t[2*x],t[2*x+1]); }
void add(int x,int l,int r,int ql,int qr){ if(qr<l||r<ql) return; if(ql<=l&&r<=qr){t[x]++;lz[x]++;return;}
  int m=(l+r)/2; add(2*x,l,m,ql,qr); add(2*x+1,m+1,r,ql,qr); t[x]=max(t[2*x],t[2*x+1])+lz[x]; }
int qry(int x,int l,int r,int ql,int qr){ if(qr<l||r<ql) return INT_MIN; if(ql<=l&&r<=qr) return t[x];
  int m=(l+r)/2; return max(qry(2*x,l,m,ql,qr),qry(2*x+1,m+1,r,ql,qr))+lz[x]; }
