  for(int i=1;i<=n;i++){ cin>>a[i]; prv[i]=last.count(a[i])?last[a[i]]:0; last[a[i]]=i; }
  t.assign(4*(n+1),0); lz.assign(4*(n+1),0);
  vector<int> dp(n+1,NEG); dp[0]=0;
  for(int L=1;L<=k;L++){ build(1,0,n,dp); vector<int> nd(n+1,NEG);
    for(int i=1;i<=n;i++){ add(1,0,n,prv[i],i-1); nd[i]=max(NEG,qry(1,0,n,0,i-1)); }
    dp=nd; }
