using namespace std; typedef long long ll; const int B=17; const ll NEG=LLONG_MIN/4;
int bv[B], bp[B];
void ins(int x,int p){ for(int b=B-1;b>=0&&x;b--){ if(!(x>>b&1)) continue;
  if(!bv[b]){ bv[b]=x; bp[b]=p; return; } if(bp[b]<p){ swap(bv[b],x); swap(bp[b],p); } x^=bv[b]; } }
ll qmax(int j){ int r=0; for(int b=B-1;b>=0;b--) if(bv[b]&&bp[b]>j) r=max(r,r^bv[b]); return r; }
int main(){ int n,K; cin>>n>>K; vector<int> a(n+1); for(int i=1;i<=n;i++) cin>>a[i];
  vector<ll> dp(n+1,NEG); dp[0]=0;
  for(int i=1;i<=n;i++){ ins(a[i],i); if(i<K) continue;
    vector<int> cand={i-K,0};
    for(int b=0;b<B;b++) if(bv[b]) cand.push_back(min(bp[b]-1,i-K));
    for(int j: cand){ if(j<0||dp[j]==NEG) continue; dp[i]=max(dp[i], dp[j]+qmax(j)); } }
  cout<<dp[n]<<endl; }

