vector<int> topo(int n, vector<vector<int>>& adj){ vector<int> in(n,0), ord; queue<int> q;
  for(int u=0;u<n;u++) for(int v: adj[u]) in[v]++;
  for(int u=0;u<n;u++) if(!in[u]) q.push(u);
  while(!q.empty()){ int u=q.front(); q.pop(); ord.push_back(u); for(int v: adj[u]) if(--in[v]==0) q.push(v); }
  if((int)ord.size()<n) return {};   // cycle
  return ord; }
