int orangesRotting(vector<vector<int>>& g){ int n=g.size(), m=g[0].size(), fresh=0, t=0; queue<pair<int,int>> q;
  for(int i=0;i<n;i++) for(int j=0;j<m;j++){ if(g[i][j]==2) q.push({i,j}); else if(g[i][j]==1) fresh++; }
  int dr[4]={1,-1,0,0}, dc[4]={0,0,1,-1};
  while(!q.empty() && fresh){ int sz=q.size(); t++;
    while(sz--){ auto [r,c]=q.front(); q.pop();
