bool canFinish(int n, vector<vector<int>>& pre){ vector<vector<int>> adj(n); vector<int> in(n,0);
  for(auto&p: pre){ adj[p[1]].push_back(p[0]); in[p[0]]++; }
  queue<int> q; for(int i=0;i<n;i++) if(!in[i]) q.push(i); int cnt=0;
  while(!q.empty()){ int u=q.front(); q.pop(); cnt++; for(int v: adj[u]) if(--in[v]==0) q.push(v); }
  return cnt==n; }
int main(){ int n,m; cin>>n>>m; vector<vector<int>> pre(m, vector<int>(2)); for(auto&p:pre) cin>>p[0]>>p[1];
  cout<<(canFinish(n,pre)?"true":"false")<<endl; }

