using namespace std; typedef long long ll; const ll INF=LLONG_MAX;
vector<ll> dijkstra(int src, vector<vector<pair<int,ll>>>& adj){ int n=adj.size(); vector<ll> d(n,INF);
  priority_queue<pair<ll,int>, vector<pair<ll,int>>, greater<>> pq; d[src]=0; pq.push({0,src});
  while(!pq.empty()){ auto [du,u]=pq.top(); pq.pop(); if(du>d[u]) continue;   // stale entry
    for(auto [v,w]: adj[u]) if(d[u]+w<d[v]){ d[v]=d[u]+w; pq.push({d[v],v}); } }
  return d; }
