  for(int i=0;i<m;i++){ int u,v; ll w; cin>>u>>v>>w; adj[u].push_back({v,w}); adj[v].push_back({u,w}); }
  auto d=dijkstra(0,adj); for(ll x: d) cout<<(x==INF? -1 : x)<<" "; cout<<endl; }

