using namespace std;
string alienOrder(vector<string>& w){ vector<set<int>> adj(26); vector<int> in(26,0); vector<bool> has(26,false);
  for(auto&s: w) for(char c: s) has[c-'a']=true;
  for(size_t i=0;i+1<w.size();i++){ string &a=w[i], &b=w[i+1]; size_t k=0;
    while(k<a.size()&&k<b.size()&&a[k]==b[k]) k++;
    if(k==min(a.size(),b.size())){ if(a.size()>b.size()) return ""; continue; }
    if(adj[a[k]-'a'].insert(b[k]-'a').second) in[b[k]-'a']++; }
  queue<int> q; for(int c=0;c<26;c++) if(has[c]&&!in[c]) q.push(c); string res;
  while(!q.empty()){ int u=q.front(); q.pop(); res+=char('a'+u); for(int v: adj[u]) if(--in[v]==0) q.push(v); }
  int tot=count(has.begin(),has.end(),true); return (int)res.size()==tot? res : ""; }
int main(){ int n; cin>>n; vector<string> w(n); for(auto&s:w) cin>>s; cout<<alienOrder(w)<<endl; }

