vector<bool> reach(int n, vector<vector<int>>& g){ vector<bool> v(n+1,false); queue<int> q; q.push(1); v[1]=true;
  while(!q.empty()){ int u=q.front(); q.pop(); for(int w: g[u]) if(!v[w]){ v[w]=true; q.push(w); } } return v; }
int main(){ int n,m; cin>>n>>m; vector<vector<int>> g(n+1), r(n+1);
  for(int i=0;i<m;i++){ int a,b; cin>>a>>b; g[a].push_back(b); r[b].push_back(a); }
  auto f=reach(n,g); for(int v=1;v<=n;v++) if(!f[v]){ cout<<"NO\n1 "<<v<<"\n"; return 0; }
  auto b=reach(n,r); for(int v=1;v<=n;v++) if(!b[v]){ cout<<"NO\n"<<v<<" 1\n"; return 0; }
  cout<<"YES\n"; }

