int main(){ int n,m; cin>>n>>m; vector<vector<long long>> h(n, vector<long long>(m)); for(auto&r:h) for(auto&x:r) cin>>x;
  vector<pair<long long,int>> cells; for(int i=0;i<n;i++) for(int j=0;j<m;j++) cells.push_back({h[i][j], i*m+j});
  sort(cells.rbegin(), cells.rend()); vector<int> dp(n*m,1); int best=0;
  int dr[4]={1,-1,0,0}, dc[4]={0,0,1,-1};
  for(auto [v,id]: cells){ int r=id/m, c=id%m;
