int minJumps(vector<int>& a){ int n=a.size(); if(n<=1) return 0; int jumps=0, end=0, far=0;
  for(int i=0;i<n-1;i++){ far=max(far,i+a[i]); if(i==end){ if(far<=i) return -1; jumps++; end=far; if(end>=n-1) break; } }
  return end>=n-1? jumps : -1; }
