#include <bits/stdc++.h>
using namespace std;
string best;
void solve(string& s,int k,int idx){ if(s<best) best=s; if(k==0||idx>=(int)s.size()) return;
  char mn=*min_element(s.begin()+idx, s.end());
  if(mn>=s[idx]){ solve(s,k,idx+1); return; }
  for(int j=idx+1;j<(int)s.size();j++) if(s[j]==mn){ swap(s[idx],s[j]); solve(s,k-1,idx+1); swap(s[idx],s[j]); } }
int main(){ string s; int k; cin>>s>>k; best=s; solve(s,k,0); cout<<best<<endl; }

