long long N,M,H; vector<long long> V;
bool ok(int s){ long long used=0, h=0;
  for(int i=s;i<N;i++){ long long v=V[i];
    while(true){ if(h==0){ if(++used>M) return false; h=H; }
      if(h>v){ h-=v; break; } if(h==v){ h=0; break; } h=0; } }   // hero dies, villain unchanged
  return true; }
int main(){ cin>>N>>M>>H; V.resize(N); for(auto&x:V) cin>>x;
  int lo=0, hi=N; while(lo<hi){ int mid=(lo+hi)/2; if(ok(mid)) hi=mid; else lo=mid+1; }
  cout<<lo<<endl; }

