vector<int> pre(const string& s){ int n=s.size(); vector<int> c(n+1,INF); c[0]=0;
  for(int j=1;j<=n;j++) for(int p=j-2;p<=j;p++) if(p>=0&&p<n&&s[p]=='L'){ int k=max(0,p-1); if(c[k]<INF) c[j]=min(c[j],c[k]+1); }
  return c; }
int main(){ int n; string s; cin>>n>>s; auto c=pre(s); string r(s.rbegin(),s.rend()); auto cr=pre(r);
  auto d=[&](int j){ return cr[n-j]; };                // cover [j,n)
  long long best=c[n];
  for(int t=0;t<n;t++){ int L=max(0,t-1), R=min(n,t+2); if(c[L]<INF&&d(R)<INF) best=min(best,(long long)c[L]+d(R)); }
  cout<<(best>=INF? -1 : best)<<endl; }

