int n; vector<ll> L;
bool ok(ll d){ ll mx=d*d, prev=LLONG_MAX;
  for(int i=0;i<n;i++){ ll need= i==0? 0 : max(0LL, L[i]-(prev-1));
    ll r=need; if(d>=2 && (r==2 || r==mx-2)) r++;
    if(r>mx) return false; prev=L[i]-r; }
  return true; }
int main(){ cin>>n; L.resize(n); for(auto&x:L) cin>>x;
  ll lo=0, hi=100000; while(lo<hi){ ll m=(lo+hi)/2; if(ok(m)) hi=m; else lo=m+1; }
  cout<<lo<<endl; }

