ll cnt(ll T){ ll c=0; for(int i=0;i<n;i++) if(v[i]>=T){ c+=(v[i]-T)/d[i]+1; if(c>M) return M+1; } return c; }
int main(){ cin>>n>>M; v.resize(n); d.resize(n); for(int i=0;i<n;i++) cin>>v[i]>>d[i];
