  for(int i=0;i<n;i++) if(v[i]>=T){ ll k=(v[i]-T)/d[i]+1; taken+=k; s+=(__int128)k*v[i]-(__int128)d[i]*k*(k-1)/2; }
  if(T-1>=1) s+=(__int128)(M-taken)*(T-1);
